package model.geo;

import model.GeoPoint;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

/**
 * The approximate position of every IANA time zone: the principal city tzdata lists
 * for it (from {@value #RESOURCE}, generated by {@code tools/gen-zone-coordinates.py}).
 * Used when the location cannot be looked up; nothing leaves the computer.
 * Fixed offsets and zones without a place ({@code Etc/UTC}, {@code GMT}, ...) have no
 * position.
 */
public final class TimeZoneLocations {

    /** The table on the classpath. */
    public static final String RESOURCE = "/geo/zone-coordinates.tsv";

    private final Map<String, GeoPoint> positions;

    private TimeZoneLocations(Map<String, GeoPoint> positions) {
        this.positions = Map.copyOf(positions);
    }

    /**
     * Loads the table from the classpath.
     *
     * @return the table
     * @throws IllegalStateException if the resource is missing or malformed
     */
    public static TimeZoneLocations load() {
        try (InputStream in = TimeZoneLocations.class.getResourceAsStream(RESOURCE)) {
            if (in == null) {
                throw new IllegalStateException("Missing resource " + RESOURCE);
            }
            Map<String, GeoPoint> positions = new HashMap<>();
            BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
            String line;
            int number = 0;
            while ((line = reader.readLine()) != null) {
                number++;
                if (line.isBlank() || line.startsWith("#")) {
                    continue;
                }
                String[] parts = line.split("\t", -1);
                if (parts.length != 3) {
                    throw new IllegalStateException(RESOURCE + " line " + number + " is malformed");
                }
                positions.put(parts[0], new GeoPoint(Double.parseDouble(parts[1]), Double.parseDouble(parts[2])));
            }
            return new TimeZoneLocations(positions);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        } catch (IllegalArgumentException e) {
            throw new IllegalStateException(RESOURCE + " is malformed", e);
        }
    }

    /**
     * @param zone a time zone
     * @return the zone's approximate position, or empty if it has none
     */
    public Optional<GeoPoint> lookup(ZoneId zone) {
        if (zone == null || zone instanceof ZoneOffset) {
            return Optional.empty();
        }
        return Optional.ofNullable(positions.get(zone.getId()));
    }

    /**
     * @return the number of zones in the table
     */
    public int size() {
        return positions.size();
    }
}
